package com.xdownload.mobile;
import android.app.*;import android.content.*;import android.os.*;import android.net.Uri;import android.widget.*;import java.io.*;import java.util.*;import java.util.concurrent.*;
/** Local audio converter. Source is read-only and output is created via the Android document picker. */
public final class AudioStudioActivity extends SecureActivity{
 static final long COPY_RESERVE=32L*1024*1024;static final String[] FORMATS={"mp3","m4a","aac","flac","wav","opus"};final ExecutorService io=Executors.newSingleThreadExecutor();volatile boolean dead=false;boolean busy=false,en;Uri source;File output;Spinner format,quality;EditText title,artist,start,end;TextView status;Button run,save,select;String ext="mp3";boolean batchOutput=false;Button batch;
 String tr(String a,String b){return en?b:a;}
 @Override public void onCreate(Bundle state){super.onCreate(state);en=Store.settings(this).getBoolean("english",false);ScrollView scroll=new ScrollView(this);LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(24,24,24,24);scroll.addView(l);TextView head=new TextView(this);head.setText(tr("استوديو الصوت","Audio Studio"));head.setTextSize(24);l.addView(head);select=new Button(this);select.setText(tr("اختيار ملف صوت أو فيديو","Choose audio/video file"));select.setOnClickListener(v->startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("*/*").addCategory(Intent.CATEGORY_OPENABLE),1));l.addView(select);batch=new Button(this);batch.setText(tr("تحويل جماعي (ZIP)","Batch conversion (ZIP)"));batch.setOnClickListener(v->startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("*/*").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true),3));l.addView(batch);format=new Spinner(this);format.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,FORMATS));l.addView(format);quality=new Spinner(this);quality.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"128 kbps","192 kbps","320 kbps"}));quality.setSelection(1);l.addView(quality);title=field(l,tr("عنوان اختياري","Optional title"),false);artist=field(l,tr("الفنان اختياري","Optional artist"),false);start=field(l,tr("بداية القص بالثواني (اختياري)","Trim start seconds (optional)"),true);end=field(l,tr("نهاية القص بالثواني (اختياري)","Trim end seconds (optional)"),true);run=new Button(this);run.setText(tr("تحويل","Convert"));run.setOnClickListener(v->convert());l.addView(run);save=new Button(this);save.setText(tr("حفظ النسخة الناتجة","Save output"));save.setOnClickListener(v->startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).setType(batchOutput?"application/zip":MediaEngine.mime(ext,true)).addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_TITLE,batchOutput?"XDownload-batch.zip":"XDownload-audio."+ext),2));l.addView(save);status=new TextView(this);status.setText(tr("التحويل محلي. معدل البت لا ينطبق على FLAC وWAV ولا يرفع جودة المصدر.","Local conversion. Bitrate does not apply to FLAC/WAV or improve source quality."));l.addView(status);setContentView(scroll);Uri incoming=getIntent().getData();if(incoming!=null&&"content".equals(incoming.getScheme())){source=incoming;status.setText(tr("تم اختيار الملف","Source selected"));}state(false);}
 EditText field(LinearLayout l,String hint,boolean number){EditText e=new EditText(this);e.setHint(hint);e.setSingleLine(true);if(number)e.setInputType(8194);l.addView(e);return e;}
 void state(boolean b){busy=b;select.setEnabled(!b);batch.setEnabled(!b);run.setEnabled(!b&&source!=null);save.setEnabled(!b&&output!=null);format.setEnabled(!b);quality.setEnabled(!b);title.setEnabled(!b);artist.setEnabled(!b);start.setEnabled(!b);end.setEnabled(!b);}
 @Override protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(result!=RESULT_OK||data==null)return;if(req==3){beginBatch(data);return;}if(data.getData()==null)return;Uri uri=data.getData();if(req==1){discardOutput();source=uri;status.setText(tr("تم اختيار الملف","Source selected"));state(false);}else if(req==2&&output!=null){File f=output;state(true);io.execute(()->{try(InputStream in=new FileInputStream(f);OutputStream out=getContentResolver().openOutputStream(uri,"w")){if(out==null)throw new IOException("Unable to open output");copy(in,out);report(tr("تم الحفظ","Saved"));}catch(Exception e){report("Save failed: "+e.getMessage());}});}}
 static void copy(InputStream in,OutputStream out)throws IOException{if(in==null||out==null)throw new IOException("Cannot access file");byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1){if(Thread.currentThread().isInterrupted())throw new IOException("Cancelled");out.write(b,0,n);}}
 void discardOutput(){batchOutput=false;if(output!=null){output.delete();output=null;}}
 static void stage(InputStream in,File dest)throws IOException{if(in==null)throw new IOException("Cannot read source");try(OutputStream out=new FileOutputStream(dest)){byte[] buf=new byte[65536];int n;long sinceCheck=0,total=0;if(dest.getUsableSpace()<COPY_RESERVE)throw new IOException("Not enough free storage");while((n=in.read(buf))!=-1){if(Thread.currentThread().isInterrupted())throw new IOException("Cancelled");if(sinceCheck>=1024*1024){if(dest.getUsableSpace()<COPY_RESERVE)throw new IOException("Not enough free storage");sinceCheck=0;}out.write(buf,0,n);sinceCheck+=n;total+=n;}if(total==0)throw new IOException("Source file is empty");if(dest.getUsableSpace()<COPY_RESERVE)throw new IOException("Not enough free storage for conversion");}}
 void beginBatch(Intent data){if(busy)return;LinkedHashSet<Uri> picked=new LinkedHashSet<>();if(data.getData()!=null)picked.add(data.getData());ClipData clips=data.getClipData();if(clips!=null){if(clips.getItemCount()>10){status.setText(tr("الحد 10 ملفات","Maximum 10 files"));return;}for(int i=0;i<clips.getItemCount();i++){Uri u=clips.getItemAt(i).getUri();if(u!=null)picked.add(u);}}if(picked.isEmpty()||picked.size()>10){status.setText(tr("اختر 1–10 ملفات","Select 1–10 files"));return;}
  final String fmt=FORMATS[format.getSelectedItemPosition()];final int rate=new int[]{128,192,320}[quality.getSelectedItemPosition()];
  new AlertDialog.Builder(this).setTitle(tr("تحويل جماعي","Batch conversion")).setMessage(picked.size()+" × "+fmt+"\n"+tr("تحويل الملفات كاملة دون قص أو تغيير البيانات الوصفية. تحفظ النسخ في ZIP واحد؛ الأصل لا يتغير.","Convert full files without trim or metadata edits. Results in one ZIP; originals are unchanged.")).setPositiveButton(tr("بدء","Start"),(d,w)->runBatch(picked,fmt,rate)).setNegativeButton(tr("إلغاء","Cancel"),null).show();
 }
 void runBatch(Collection<Uri> picked,String fmt,int rate){if(busy)return;discardOutput();state(true);status.setText(tr("جارٍ التحويل الجماعي…","Batch conversion…"));io.execute(()->{File zip=null,input=null,encoded=null;try{
  zip=File.createTempFile("studio-out-",".zip",getCacheDir());HashSet<String> used=new HashSet<>();int count=0;long combined=0;
  try(java.util.zip.ZipOutputStream out=new java.util.zip.ZipOutputStream(new BufferedOutputStream(new FileOutputStream(zip)))){for(Uri u:picked){if(dead||Thread.currentThread().isInterrupted())throw new IOException("Cancelled");
   input=File.createTempFile("studio-in-",".media",getCacheDir());encoded=File.createTempFile("studio-out-","."+fmt,getCacheDir());
   try(InputStream in=getContentResolver().openInputStream(u)){stage(in,input);}encode(this,input,encoded,fmt,rate,"","",0,-1);
   combined+=encoded.length();if(combined>512L*1024*1024||getCacheDir().getUsableSpace()<COPY_RESERVE+encoded.length())throw new IOException("Batch output/storage limit");
   String sourceName="audio-"+(count+1);try(android.database.Cursor c=getContentResolver().query(u,new String[]{android.provider.OpenableColumns.DISPLAY_NAME},null,null,null)){if(c!=null&&c.moveToFirst())sourceName=c.getString(0);}catch(Exception ignored){}sourceName=HttpEngine.safeName(sourceName);int dot=sourceName.lastIndexOf('.');if(dot>0)sourceName=sourceName.substring(0,dot);out.putNextEntry(new java.util.zip.ZipEntry(FileTools.uniqueEntry(sourceName+"."+fmt,used)));try(InputStream in=new FileInputStream(encoded)){copy(in,out);}out.closeEntry();input.delete();input=null;encoded.delete();encoded=null;count++;final int done=count;runOnUiThread(()->{if(!dead)status.setText(done+" / "+picked.size());});}}
  File done=zip;zip=null;runOnUiThread(()->{if(dead){done.delete();return;}output=done;batchOutput=true;status.setText(tr("ZIP جاهز للحفظ: ","ZIP ready: ")+MainActivity.size(done.length()));state(false);});
 }catch(Exception|LinkageError ex){report(tr("فشل التحويل الجماعي: ","Batch failed: ")+ex.getMessage());}finally{if(input!=null)input.delete();if(encoded!=null)encoded.delete();if(zip!=null)zip.delete();}});}
 void convert(){if(busy||source==null)return;String fmt=FORMATS[format.getSelectedItemPosition()];int rate=new int[]{128,192,320}[quality.getSelectedItemPosition()];String name=title.getText().toString(),author=artist.getText().toString();double a=0,b=-1;try{if(!start.getText().toString().isEmpty())a=Double.parseDouble(start.getText().toString());if(!end.getText().toString().isEmpty())b=Double.parseDouble(end.getText().toString());if(!Double.isFinite(a)||!Double.isFinite(b)||a<0||b!=-1&&b<=a)throw new IllegalArgumentException();}catch(Exception e){status.setText(tr("أوقات القص غير صحيحة","Invalid trim times"));return;}final double from=a,to=b;Uri selected=source;discardOutput();state(true);status.setText(tr("جارٍ التحويل…","Converting…"));io.execute(()->{File input=null,result=null;try{input=File.createTempFile("studio-in-",".tmp",getCacheDir());result=File.createTempFile("studio-out-","."+fmt,getCacheDir());try(InputStream in=getContentResolver().openInputStream(selected)){stage(in,input);}encode(this,input,result,fmt,rate,name,author,from,to);if(dead){result.delete();return;}final File done=result;result=null;runOnUiThread(()->{if(dead){done.delete();return;}if(output!=null)output.delete();output=done;ext=fmt;status.setText(tr("جاهز للحفظ: ","Ready to save: ")+MainActivity.size(done.length()));state(false);});}catch(Exception|LinkageError e){report("Conversion failed: "+e.getMessage());}finally{if(input!=null)input.delete();if(result!=null)result.delete();}});}
 static void encode(Context context,File in,File out,String fmt,int rate,String title,String artist,double start,double end)throws IOException{
  String codec;switch(fmt){case "mp3":codec="libmp3lame";break;case "m4a":case "aac":codec="aac";break;case "flac":codec="flac";break;case "wav":codec="pcm_s16le";break;case "opus":codec="libopus";break;default:throw new IOException("Invalid output format");}
  if(rate!=128&&rate!=192&&rate!=320||!Double.isFinite(start)||!Double.isFinite(end)||start<0||end!=-1&&end<=start)throw new IOException("Invalid audio settings");ArrayList<String> args=new ArrayList<>(Arrays.asList("-y","-i",in.getAbsolutePath(),"-vn","-map","0:a:0","-c:a",codec));if(start>0)args.addAll(Arrays.asList("-ss",Double.toString(start)));if(end>=0)args.addAll(Arrays.asList("-t",Double.toString(end-start)));if(!fmt.equals("flac")&&!fmt.equals("wav"))args.addAll(Arrays.asList("-b:a",rate+"k"));if(!title.isEmpty())args.addAll(Arrays.asList("-metadata","title="+title.substring(0,Math.min(title.length(),200))));if(!artist.isEmpty())args.addAll(Arrays.asList("-metadata","artist="+artist.substring(0,Math.min(artist.length(),200))));args.add(out.getAbsolutePath());NativeMedia.run(context,args.toArray(new String[0]));if(out.length()<44)throw new IOException("Encoder did not produce valid output");}
 void report(String text){runOnUiThread(()->{if(!dead){status.setText(text);state(false);}});}
 @Override protected void onDestroy(){dead=true;io.shutdownNow();discardOutput();super.onDestroy();}
}